    )

mapper.update:
UPDATE monthly_repayment
SET repayment_status = #{status}, repayment_time = #{repaymentTime}
WHERE repayment_id = #{repaymentId}

mapper.select:
SELECT COALESCE(SUM(mr.repayment_amount), 0) AS overdueAmount, COUNT(DISTINCT rp.user_id) AS overdueCustomers, COALESCE(ROUND(AVG(DATEDIFF(NOW(), mr.due_date))), 0) AS avgOverdueDays FROM monthly_repayment mr INNER JOIN repayment_plan rp ON mr.plan_id = rp.plan_id WHERE mr.repayment_status = 'overdue'
AND mr.due_date >= #{startDate}
AND mr.due_date <= CONCAT(#{endDate}, ' 23:59:59')

SELECT COUNT(1) FROM monthly_repayment mr INNER JOIN repayment_plan rp ON mr.plan_id = rp.plan_id WHERE mr.repayment_status IN ('unpaid', 'overdue', 'paid')
AND mr.due_date >= #{startDate}
AND mr.due_date <= CONCAT(#{endDate}, ' 23:59:59')
